using System.Reflection;
using System.Text.RegularExpressions;
using System.Runtime.CompilerServices;
using TownOfHost;
using TownOfHost.Modules;
using TownOfHost.Roles.Core;
using TownOfHost.Roles.Core.Interfaces;
using TownOfHost.Roles.Impostor;
using UnityEngine;
static partial class Program {
 static int passed,failed,game=100;
 static void Check(bool value,string reason="assertion"){if(!value)throw new Exception(reason);}
 static void Eq<T>(T expected,T actual){if(!Equals(expected,actual))throw new Exception($"expected {expected}, actual {actual}");}
 static T Get<T>(object value,string field){var type=value.GetType();return (T)(type.GetField(field,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)?.GetValue(value)??type.GetProperty(field,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public)?.GetValue(value));}
 static void Set(object value,string field,object data)=>value.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).SetValue(value,data);
 static void Test(string name,Action action){try{Reset();action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+" "+e);}}
 static void Reset(){TownOfHost.Main.NormalOptions=new NormalOptions();Time.time=0;Time.fixedDeltaTime=.02f;GameStates.IsInTask=true;GameStates.IsMeeting=GameStates.CalledMeeting=false;MeetingHud.Instance=null;AmongUsClient.Instance=new(){GameId=++game};PlayerCatch.All.Clear();PlayerState.Reset();CustomRoleManager.AllActiveRoles.Clear();CustomRoleManager.Accept=CustomRoleManager.Validate=true;CustomRoleManager.Throw=false;CustomRoleManager.Attempts=0;CustomRoleManager.Observe=null;CheckMurderPatch.TimeSinceLastKill.Clear();TownOfHost.Main.AllPlayerSpeed.Clear();OptionItem.All.Clear();LateTask.Jobs.Clear();Sender.Packets.Clear();CustomNetObject.Reset();PhysicsHelpers.Block=null;TMPro.TextMeshPro.ResetLayout();SuddenDeathMode.NowSuddenDeathMode=false;MeetingStates.FirstMeeting=false;Options.firstturnmeeting=Options.IsStandardHAS=false;Options.HideAndSeekKillDelayTimer=0;Nova.RoleInfo.Setup();PlayerControl.LocalPlayer=P(0);}
 static PlayerControl P(byte id,CustomRoles role=CustomRoles.Crewmate,float x=0,float y=0){var p=new PlayerControl{PlayerId=id,Role=role,inVent=false};p.transform.position=new(x,y);PlayerCatch.All.Add(p);TownOfHost.Main.AllPlayerSpeed[id]=1.25f;return p;}
 static Nova N(byte id=1)=>new(P(id,CustomRoles.Nova));
 static void Tick(float time,params Nova[] roles){LateTask.At(time);foreach(var role in roles)role.OnFixedUpdate(role.Player);CustomNetObject.Tick();}
 static void Warm(params Nova[] roles){Tick(Time.time,roles);for(int i=0;i<120&&!roles.All(r=>Get<bool>(r,"TilesReady"));i++)Tick(Time.time+.41f,roles);Check(roles.All(r=>Get<bool>(r,"TilesReady")),"visual warmup incomplete");}
 static bool Press(Nova n){bool adjust=true;bool? reset=true;((IUsePhantomButton)n).OnClick(ref adjust,ref reset);Check(!adjust,"ordinary kill CD changed");return reset==true;}
 static void Start(Nova n){Warm(n);Check(!Press(n));Check(Get<bool>(n,"charging"));}
 static void Lock(Nova n){Tick(Time.time+3.01f,n);Check(Press(n));Check(Get<bool>(n,"waiting"));}
 static void Fire(Nova n){Tick(Time.time+1.01f,n);Check(Get<bool>(n,"beaming"));Tick(Time.time+.02f,n);}
 static string Source(string relative,[CallerFilePath]string file="")=>File.ReadAllText(Path.GetFullPath(Path.Combine(Path.GetDirectoryName(file),"../..",relative)));
 static void Main(string[] args){
  if(args.Contains("--map-bench")){MapBench();return;}
  if(args.Contains("--layout-repro")){LayoutRepro();return;}
  if(args.Contains("--layout-bench")){LayoutBench();return;}
  if(args.Contains("--range-bench")){RangeBench();return;}
  Test("official metadata options and defaults",()=>{Eq(CustomRoles.Nova,Nova.RoleInfo.RoleName);Eq(588,(int)Nova.RoleInfo.RoleName);Eq(992900,Nova.RoleInfo.ConfigId);Eq(From.UchuAddon,Nova.RoleInfo.From);Eq(AmongUs.GameOptions.RoleTypes.Phantom,Nova.RoleInfo.BaseRoleType());foreach(var(id,value)in new[]{(992910,0f),(992911,30f),(992912,1.25f),(992913,3f),(992914,30f),(992915,1f)})Eq(value,OptionItem.All[id].Value);Eq(6,OptionItem.All.Count);});
  foreach(int id in new[]{992911,992912,992913,992914,992915})Test("option range "+id,()=>{var r=(FloatRule)OptionItem.All[id].Rule;Check(r.Min<=OptionItem.All[id].Value&&r.Max>=OptionItem.All[id].Value&&r.Step>0);});
  Test("Nova main-role exception preserves every legacy classification",()=>{foreach(var role in Enum.GetValues<CustomRoles>())Eq(role==CustomRoles.Nova||role<CustomRoles.NotAssigned,role.IsMainRole());Eq(500,(int)CustomRoles.NotAssigned);Check(!CustomRoles.LastImpostor.IsMainRole());});
  foreach(int mode in new[]{0,1,2})foreach(float angle in new[]{-180f,-135f,-90f,-45f,0f,45f,90f,135f,180f})Test($"snap {mode}/{angle}",()=>{float result=NovaBeamRules.SnapAngle(angle,mode);if(mode==0)Eq(angle,result);if(mode==1)Eq(Math.Abs(angle)<=90?0f:180f,result);if(mode==2)Eq(MathF.Round(angle/90)*90,result);});
  foreach(float invalid in new[]{float.NaN,float.PositiveInfinity,float.NegativeInfinity})Test("invalid aim "+invalid,()=>{Eq(0f,NovaBeamRules.SnapAngle(invalid,0));Check(!NovaBeamRules.ValidState(false,false,false,invalid));Check(!NovaBeamRules.Contains(invalid,0,10,1,.5f));});
  foreach(var(along,side,expected)in new[]{(.49f,0f,false),(.5f,0f,true),(10f,0f,true),(10.01f,0f,false),(2f,.925f,true),(2f,.926f,false),(-1f,0f,false)})Test($"beam boundary {along}/{side}",()=>Eq(expected,NovaBeamRules.Contains(along,side,10,1.25f,.5f)));
  Test("unready press has no charge damage or cooldown",()=>{var n=N();Check(!Press(n));Check(!Get<bool>(n,"charging"));Eq(0,Sender.Packets.Count);Eq(0,CustomRoleManager.Attempts);Eq(1.25f,TownOfHost.Main.AllPlayerSpeed[1]);});
  Test("creation waits four seconds then serializes",()=>{var n=N();Tick(0,n);Tick(3.99f,n);Eq(0,CustomNetObject.AllObjects.Count);Tick(4.01f,n);Eq(0,CustomNetObject.AllObjects.Count);Tick(4.42f,n);Eq(1,CustomNetObject.AllObjects.Count);Check(!Get<bool>(n,"TilesReady"));});
  Test("first press charges and slows owner",()=>{var n=N();Start(n);Eq(.15f,TownOfHost.Main.AllPlayerSpeed[1]);Check(!Get<bool>(n,"waiting"));Eq(0,CustomRoleManager.Attempts);});
  Test("second press before three seconds is ignored",()=>{var n=N();Start(n);Tick(Time.time+2.99f,n);Check(!Press(n));Check(Get<bool>(n,"charging"));});
  Test("second press locks direction and starts delay",()=>{var n=N();Start(n);Lock(n);Eq(TownOfHost.Main.MinSpeed,TownOfHost.Main.AllPlayerSpeed[1]);Tick(Time.time+.99f,n);Check(Get<bool>(n,"waiting"));Eq(0,CustomRoleManager.Attempts);});
  Test("multiple targets hit once with evaporation reason",()=>{var n=N();Start(n);var a=P(2,x:2);var b=P(3,x:5);Lock(n);Fire(n);Check(!a.IsAlive()&&!b.IsAlive());Eq(2,CustomRoleManager.Attempts);Eq(CustomDeathReason.Evaporation,PlayerState.GetByPlayerId(2).DeathReason);Tick(Time.time+.2f,n);Eq(2,CustomRoleManager.Attempts);});
  Test("protected target not retried each frame",()=>{var n=N();Start(n);var a=P(2,x:2);a.Guarded=true;Lock(n);Fire(n);for(int i=0;i<20;i++)Tick(Time.time+.04f,n);Check(a.IsAlive());Eq(1,CustomRoleManager.Attempts);});
  Test("role defense preserved",()=>{var n=N();Start(n);var a=P(2,x:2);_ =new Defense(a);Lock(n);Fire(n);Check(a.IsAlive());Eq(1,CustomRoleManager.Attempts);});
  Test("reflection stops remaining beam targets",()=>{var n=N();Start(n);var a=P(2,x:2);var b=P(3,x:3);_ =new Defense(a,n.Player);Lock(n);Fire(n);Check(!n.Player.IsAlive()&&a.IsAlive()&&b.IsAlive());Eq(1,CustomRoleManager.Attempts);});
  foreach(bool sudden in new[]{false,true})Test("teammate policy sudden="+sudden,()=>{var n=N();Start(n);var friend=P(2,CustomRoles.DoubleKiller,2);SuddenDeathMode.NowSuddenDeathMode=sudden;Lock(n);Fire(n);Eq(!sudden,friend.IsAlive());});
  Test("dead disconnected and dummy targets skipped",()=>{var n=N();Start(n);P(2,x:2).Data.IsDead=true;P(3,x:2).Data.Disconnected=true;P(254,x:2);Lock(n);Fire(n);Eq(0,CustomRoleManager.Attempts);});
  Test("targets outside beam survive",()=>{var n=N();Start(n);var a=P(2,x:-2);var b=P(3,x:3,y:2);Lock(n);Fire(n);Check(a.IsAlive()&&b.IsAlive());});
  Test("wall cannot shorten draw or damage reach",()=>{var n=N();Start(n);var a=P(2,x:2);var b=P(3,x:7);PhysicsHelpers.Block=(_,_,distance,_)=>distance>=4.2f;Lock(n);Fire(n);Check(!a.IsAlive()&&!b.IsAlive());Eq(50f,Get<float>(n,"reach"));});
  Test("near wall cannot cancel a fully prepared penetrating beam",()=>{var n=N();Start(n);var target=P(2,x:.55f);PhysicsHelpers.Block=(_,_,distance,_)=>distance>=.1f;Lock(n);Fire(n);Check(Get<bool>(n,"beaming")&&!target.IsAlive());Eq(1,CustomRoleManager.Attempts);Tick(Time.time+1.51f,n);Eq(1.25f,TownOfHost.Main.AllPlayerSpeed[1]);});
  Test("beam ends after visible 1.5 seconds restoring speed",()=>{var n=N();Start(n);Lock(n);Fire(n);Tick(Time.time+1.51f,n);Check(!Get<bool>(n,"beaming"));Eq(1.25f,TownOfHost.Main.AllPlayerSpeed[1]);});
  Test("post-shot cooldown is authoritative",()=>{var n=N();Start(n);Lock(n);Fire(n);Tick(Time.time+1.51f,n);Check(!Press(n));Check(!Get<bool>(n,"charging"));Tick(Get<float>(n,"readyAt")+.01f,n);Press(n);Check(Get<bool>(n,"charging"));});
  Test("maximum charge hold auto-confirms",()=>{var n=N();Start(n);Tick(Time.time+13.01f,n);Check(Get<bool>(n,"waiting"));Check(n.Player.ResetCount>0);});
  Test("free aim turns gradually with movement",()=>{var n=N();Start(n);n.Player.transform.position=new(0,.1f);Tick(Time.time+.02f,n);float a=Get<float>(n,"angle");Check(a>0&&a<90);});
  Test("stationary aim stays still",()=>{var n=N();Start(n);Set(n,"angle",22f);Tick(Time.time+.1f,n);Eq(22f,Get<float>(n,"angle"));});
  foreach(int mode in new[]{1,2})Test("movement aim mode "+mode,()=>{OptionItem.All[992910].Value=mode;var n=N();Start(n);n.Player.transform.position=new(.05f,.1f);Tick(Time.time+.02f,n);Eq(mode==1?0f:90f,Get<float>(n,"angle"));});
  Test("aim leash returns body and ignores stale return movement",()=>{var n=N();Start(n);n.Player.transform.position=new(.3f,0);Tick(Time.time+.02f,n);Check(n.Player.Teleports>0);Eq(0f,n.Player.transform.position.x);float a=Get<float>(n,"angle");n.Player.transform.position=new(0,.01f);Tick(Time.time+.02f,n);Eq(a,Get<float>(n,"angle"));});
  Test("same-ID Unity wrapper is accepted",()=>{var n=N();Start(n);var wrapper=new PlayerControl{PlayerId=1};n.Player.transform.position=new(0,.1f);Time.time+=.02f;n.OnFixedUpdate(wrapper);Check(Get<float>(n,"angle")>0);});
  foreach(string phase in new[]{"charging","waiting","beaming"})foreach(string end in new[]{"report","meeting","death","destroy","task-end","called"})Test($"{phase} cancelled by {end}",()=>{var n=N();Start(n);if(phase!="charging")Lock(n);if(phase=="beaming")Fire(n);if(end=="report")n.OnReportDeadBody(null,null);if(end=="meeting")n.OnStartMeeting();if(end=="death"){n.Player.Data.IsDead=true;n.OnDead(n.Player);}if(end=="destroy")n.OnDestroy();if(end=="task-end"){GameStates.IsInTask=false;Tick(Time.time+.01f,n);}if(end=="called"){GameStates.CalledMeeting=true;Tick(Time.time+.01f,n);}Check(!Get<bool>(n,"charging")&&!Get<bool>(n,"waiting")&&!Get<bool>(n,"beaming"));Eq(1.25f,TownOfHost.Main.AllPlayerSpeed[1]);Eq(0,CustomNetObject.AllObjects.Count);});
  Test("queued creations cannot resurrect after disposal",()=>{var n=N();Tick(0,n);Tick(4.01f,n);n.OnDestroy();Tick(10,n);Eq(0,CustomNetObject.AllObjects.Count);Check(!Get<bool>(n,"tilesSpawned"));});
  Test("delayed hide cannot recreate a removed tile",()=>{var n=N();Warm(n);n.OnDestroy();Tick(Time.time+10,n);Eq(0,CustomNetObject.AllObjects.Count);});
  Test("cleanup preserves external speed change",()=>{var n=N();Start(n);TownOfHost.Main.AllPlayerSpeed[1]=2.5f;n.OnDestroy();Eq(2.5f,TownOfHost.Main.AllPlayerSpeed[1]);});
  Test("recycled player ID not overwritten",()=>{var n=N();Start(n);PlayerCatch.All.Remove(n.Player);P(1);TownOfHost.Main.AllPlayerSpeed[1]=1.7f;n.OnDestroy();Eq(1.7f,TownOfHost.Main.AllPlayerSpeed[1]);});
  Test("two owners have separate profiles and state",()=>{OptionItem.All[992912].Value=.5f;var a=N(1);OptionItem.All[992912].Value=2.5f;var b=N(2);Warm(a,b);Check(Get<NovaBeamTile.RenderProfile>(a,"render").TileWorldSize!=Get<NovaBeamTile.RenderProfile>(b,"render").TileWorldSize);Press(a);Eq(.15f,TownOfHost.Main.AllPlayerSpeed[1]);Eq(1.25f,TownOfHost.Main.AllPlayerSpeed[2]);Press(b);a.OnDestroy();Eq(1.25f,TownOfHost.Main.AllPlayerSpeed[1]);Eq(.15f,TownOfHost.Main.AllPlayerSpeed[2]);Check(Get<bool>(b,"charging"));});
  Test("cooldown options are per-owner snapshots",()=>{OptionItem.All[992911].Value=20;var a=N(1);OptionItem.All[992911].Value=60;var b=N(2);a.ApplyGameOptions(null);Eq(20f,AmongUs.GameOptions.AURoleOptions.PhantomCooldown);b.ApplyGameOptions(null);Eq(60f,AmongUs.GameOptions.AURoleOptions.PhantomCooldown);});
  Test("native appearance path replaces raw dummy name RPC",()=>{var n=N();Start(n);Lock(n);Fire(n);Eq(0,CustomNetObject.RawNameCalls);Check(CustomNetObject.Names.Any(x=>x.Contains("mark")||x.Contains("rotate")));});
  Test("host outfit restored on serialization failure",()=>{var n=N();Warm(n);var o=PlayerControl.LocalPlayer.Data.DefaultOutfit;var old=(o.PlayerName,o.ColorId,o.HatId,o.SkinId,o.PetId,o.VisorId);CustomNetObject.ThrowAppearance=true;Press(n);Eq(old,(o.PlayerName,o.ColorId,o.HatId,o.SkinId,o.PetId,o.VisorId));Tick(Time.time+.02f,n);Check(!Get<bool>(n,"charging"));Eq(1.25f,TownOfHost.Main.AllPlayerSpeed[1]);Eq(0,CustomRoleManager.Attempts);});
  Test("failed cosmetic move cannot cause invisible hit",()=>{var n=N();Start(n);P(2,x:2);Lock(n);CustomNetObject.ThrowMove=true;Tick(Time.time+1.01f,n);Tick(Time.time+.02f,n);Eq(0,CustomRoleManager.Attempts);Check(!Get<bool>(n,"beaming"));});
  Test("budget timeout cancels beam before damage",()=>{var n=N();Start(n);P(2,x:2);Lock(n);while(NovaVisualTraffic.Take(AmongUsClient.Instance.GameId,Time.time)){}Tick(Time.time+1.01f,n);Tick(Time.time+.02f,n);Eq(0,CustomRoleManager.Attempts);Tick(Time.time+2.01f,n);Check(!Get<bool>(n,"beaming"));Eq(1.25f,TownOfHost.Main.AllPlayerSpeed[1]);});
  Test("traffic budget bound expiry and new game",()=>{for(int i=0;i<120;i++)Check(NovaVisualTraffic.Take(5000,0));Check(!NovaVisualTraffic.Take(5000,0));Check(NovaVisualTraffic.Take(5000,6));Check(NovaVisualTraffic.Take(5001,6));});
  Test("wire payload matches official three booleans and float",()=>{var n=N();Start(n);var data=Sender.Packets.Last();Eq(9,data.Length);Eq((byte)1,data[0]);Eq((byte)1,data[1]);});
  foreach(int len in Enumerable.Range(0,7))Test("short RPC ignored "+len,()=>{var n=N();AmongUsClient.Instance.AmHost=false;n.ReceiveRPC(new Hazel.MessageReader(new byte[len]));Check(!Get<bool>(n,"charging"));});
  foreach(var f in new[]{(true,true,false),(true,false,true),(false,true,true),(true,true,true)})Test("conflicting RPC flags "+f,()=>{var n=N();AmongUsClient.Instance.AmHost=false;var writer=new Hazel.MessageWriter();writer.Write(f.Item1);writer.Write(f.Item2);writer.Write(f.Item3);writer.Write(0f);n.ReceiveRPC(new(writer.ToByteArray(false)));Check(!Get<bool>(n,"charging")&&!Get<bool>(n,"waiting")&&!Get<bool>(n,"beaming"));});
  Test("remote state updates UI but cannot damage",()=>{var n=N();AmongUsClient.Instance.AmHost=false;var writer=new Hazel.MessageWriter();writer.Write(true);writer.Write(false);writer.Write(false);writer.Write(45f);n.ReceiveRPC(new(writer.ToByteArray(false)));Check(Get<bool>(n,"charging"));Eq(45f,Get<float>(n,"angle"));n.OnFixedUpdate(n.Player);Eq(0,CustomRoleManager.Attempts);});
  Test("host ignores client role state",()=>{var n=N();var writer=new Hazel.MessageWriter();writer.Write(true);writer.Write(false);writer.Write(false);writer.Write(45f);n.ReceiveRPC(new(writer.ToByteArray(false)));Check(!Get<bool>(n,"charging"));});
  Test("charging hint stays private to owner",()=>{var n=N();Start(n);Eq("",n.GetLowerText(P(2)));Check(n.GetLowerText(n.Player).Length>0);Eq("",n.GetLowerText(n.Player,isForMeeting:true));});
  Test("rejected pet-fire source is not restored",()=>{var src=Source("Roles/Impostor/Nova.cs");foreach(var text in new[]{"OnPet","HasHit","OptionSuicide","NovaSuicide"})Check(!src.Contains(text));Check(src.Contains("from: From.UchuAddon"));});
  Test("IDs and addon boundary remain explicit",()=>{var src=Source("Roles/Core/CustomRoleManager.cs");Check(src.Contains("Nova = 588")&&src.Contains("NotAssigned = 500")&&src.Contains("LessThan = 376"));Check(Source("Roles/Core/SimpleRoleInfo.cs").Contains("UchuAddon = 25"));});
  Test("main-role entry paths recognize high-ID Nova",()=>{foreach(var path in new[]{"Modules/RPC.cs","Modules/ExtendedPlayerControl/ExtendedRpc.cs","Modules/OptionItem/AssignOptionItem.cs","Modules/OptionItem/FilterOptionItem.cs","Roles/Crewmate/SuspiciousTeller.cs","Roles/AddOns/Common/Buff/Damudo.cs"}){var src=Regex.Replace(Source(path),@"//[^\n]*|/\*.*?\*/","",RegexOptions.Singleline);Check(!src.Contains("role < CustomRoles.NotAssigned")&&!src.Contains("role >= CustomRoles.NotAssigned"),path);}});
  foreach(float width in new[]{.25f,.5f,1.25f,2.5f,5f})foreach(float angle in new[]{0f,45f,90f,180f,225f,270f})Test($"width and angle coverage {width}/{angle}",()=>{OptionItem.All[992912].Value=width;var n=N();Start(n);Set(n,"angle",angle);var a=P(2,x:MathF.Cos(angle*Mathf.Deg2Rad)*3,y:MathF.Sin(angle*Mathf.Deg2Rad)*3);Lock(n);Fire(n);Check(!a.IsAlive(),"valid visible beam must hit on its center line");});
  Test("smooth beam branch spans bounded endpoints",()=>{var n=N();Start(n);var profile=Get<NovaBeamTile.RenderProfile>(n,"render");Set(profile,"smoothFont","synthetic");Set(profile,"barSize",2000);Set(profile,"<BarLength>k__BackingField",2f);CustomNetObject.Names.Clear();var a=P(2,x:3);Lock(n);Fire(n);Check(!a.IsAlive());Check(CustomNetObject.Names.Any(x=>x.Contains("rotate")));Eq(0,CustomNetObject.RawNameCalls);});
  Test("short wall preserves full smooth beam instead of clipping to grid",()=>{var n=N();Start(n);var profile=Get<NovaBeamTile.RenderProfile>(n,"render");Set(profile,"smoothFont","synthetic");Set(profile,"barSize",2000);Set(profile,"<BarLength>k__BackingField",4f);PhysicsHelpers.Block=(_,_,distance,_)=>distance>=2.2f;CustomNetObject.Names.Clear();var a=P(2,x:1);var b=P(3,x:3);Lock(n);Fire(n);Check(!a.IsAlive()&&!b.IsAlive());Check(!CustomNetObject.Names.Any(x=>x.Contains("mark")));Check(CustomNetObject.Names.Any(x=>x.Contains("rotate")));});
  Test("borrowed Nova keeps neutral team policy",()=>{var p=P(1,CustomRoles.JackalWolf);_ =new Defense(p);var n=new Nova(p);Start(n);var target=P(2,CustomRoles.DoubleKiller,3);Lock(n);Fire(n);Check(!target.IsAlive());});
  Test("NaN aim cancellation cannot auto-fire later in same tick",()=>{var n=N();Start(n);n.Player.transform.position=new(float.NaN,0);Tick(Time.time+13.01f,n);Check(!Get<bool>(n,"charging")&&!Get<bool>(n,"waiting")&&!Get<bool>(n,"beaming"));Eq(1.25f,TownOfHost.Main.AllPlayerSpeed[1]);Eq(0,CustomRoleManager.Attempts);});
  foreach(string state in new[]{"client","not-task","called","meeting","ladder","vent","disconnected"})Test("start rejected in "+state,()=>{var n=N();Warm(n);if(state=="client")AmongUsClient.Instance.AmHost=false;if(state=="not-task")GameStates.IsInTask=false;if(state=="called")GameStates.CalledMeeting=true;if(state=="meeting")MeetingHud.Instance=new();if(state=="ladder")n.Player.onLadder=true;if(state=="vent")n.Player.inVent=true;if(state=="disconnected")n.Player.Data.Disconnected=true;Press(n);Check(!Get<bool>(n,"charging"));Eq(0,CustomRoleManager.Attempts);});
  foreach(float invalid in new[]{float.NaN,float.PositiveInfinity,float.NegativeInfinity,36001f})Test("wire angle rejected "+invalid,()=>{var n=N();AmongUsClient.Instance.AmHost=false;var writer=new Hazel.MessageWriter();writer.Write(true);writer.Write(false);writer.Write(false);writer.Write(invalid);n.ReceiveRPC(new(writer.ToByteArray(false)));Check(!Get<bool>(n,"charging"));});
  Test("owner's regular kill cooldown remains independently configured",()=>{OptionItem.All[992914].Value=45;OptionItem.All[992911].Value=20;var n=N();Eq(45f,n.CalculateKillCooldown());n.ApplyGameOptions(null);Eq(20f,AmongUs.GameOptions.AURoleOptions.PhantomCooldown);});
  foreach(byte status in new byte[]{0,1,2})Test("remote visual readiness status "+status,()=>{var n=N();AmongUsClient.Instance.AmHost=false;var data=new Hazel.MessageWriter();data.Write(false);data.Write(false);data.Write(false);data.Write(0f);data.Write(status);n.ReceiveRPC(new(data.ToByteArray(false)));Eq(status,Get<byte>(n,"remoteVisualStatus"));string hint=n.GetLowerText(n.Player);Check(hint.Contains(status==0?"NovaPreparing":status==1?"NovaControls":"NovaVisualUnavailable"));});
  Test("legacy seven-byte idle state remains readable",()=>{var n=N();AmongUsClient.Instance.AmHost=false;n.ReceiveRPC(new(new byte[7]));Eq((byte)1,Get<byte>(n,"remoteVisualStatus"));Check(n.GetLowerText(n.Player).Contains("NovaControls"));});
  Test("unknown visual state rejected atomically",()=>{var n=N();AmongUsClient.Instance.AmHost=false;var data=new Hazel.MessageWriter();data.Write(true);data.Write(false);data.Write(false);data.Write(45f);data.Write((byte)3);n.ReceiveRPC(new(data.ToByteArray(false)));Check(!Get<bool>(n,"charging"));Eq(0f,Get<float>(n,"angle"));});
  Test("fallback beam names fit existing UTF8 network budget",()=>{var n=N();Start(n);Lock(n);Fire(n);Check(CustomNetObject.Names.All(name=>System.Text.Encoding.UTF8.GetByteCount(name)<=800));});
  Test("oversized visual is rejected without raw network name",()=>{var n=N();Warm(n);var tile=((List<NovaBeamTile>)Get<List<NovaBeamTile>>(n,"tiles"))[0];typeof(NovaBeamTile).GetMethod("SendTileName",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(tile,new object[]{new string('あ',300)});Check(tile.Failed);Eq(0,CustomNetObject.RawNameCalls);Check(!Get<bool>(n,"TilesReady"));});
  Test("invalid cosmetic color safely uses white guide",()=>{var n=N();Warm(n);n.Player.Data.DefaultOutfit.ColorId=1000;Press(n);Check(Get<bool>(n,"charging"));});
